dataTableFormat:
{
  "is multi section": "true",
  "tab groups": [
    [
      {
        "section": "globalAssociations",
        "label": "Global Associations"
      },
      {
        "section": "clumpedMatrix",
        "label": "Clumped Matrix"
      }
    ]
  ],
  "sections": [
    {
      "section id": "globalAssociations",
      "header": "Global Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "global-associations",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "cumulate data": "true"
      },
      "search parameters": [
        {
          "parameter": "phenotype",
          "label": "Phenotype",
          "type": "list",
          "values": "kp phenotypes"
        }
      ],
      "table format": {
        "group by": [
          "Phenotype"
        ],
        "compare data": {
          "key field": "Variant ID",
          "fields to compare": [
            "Phenotype",
            "P-Value",
            "P-Value(-log10)",
            "Beta",
            "Standard Error",
            "Z Score",
            "MAF",
            "Clump",
            "Clumped Region",
            "Nearest Genes"
          ]
        },
        "initial sort by": {
          "field": "P-Value",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "dbSNP",
            "raw field": "dbSNP"
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "P-Value(-log10)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Clump",
            "raw field": "clump"
          },
          {
            "type": "join multi",
            "field name": "Clumped Region",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": [
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "array to string",
            "field name": "Nearest Genes",
            "raw field": "nearest",
            "separate by": ","
          },
          {
            "type": "join multi",
            "field name": "View in VS",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd",
              "phenotype"
            ],
            "join by": [
              ":",
              "-",
              "&phenotype="
            ]
          }
        ],
        "top rows": [
          "Variant ID",
          "dbSNP",
          "Phenotype",
          "P-Value",
          "Beta",
          "Standard Error",
          "Z Score",
          "MAF",
          "Clump",
          "Clumped Region",
          "Nearest Genes",
          "View in VS"
        ],
        "locus field": "Variant ID",
        "rows per page": 20,
        "column formatting": {
          "View in VS": {
            "type": [
              "link"
            ],
            "link to": "/research.html?pageid=kp_variant_sifter&region=",
            "link type": "button",
            "link label": "Open",
            "new tab": "true"
          }
        }
      },
      "visualizer": {
        "type": "manhattan bitmap plot",
        "x axis field": "Locus",
        "y axis field": "P-Value(-log10)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value"
        ],
        "height": 100
      }
    },
    {
      "section id": "clumpedMatrix",
      "header": "Clumped Matrix",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "clumped-matrix",
        "parameters": [
          "primaryPhenotype",
          "secondaryPhenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "cumulate data": "true"
      },
      "search parameters": [
        {
          "parameter": "primaryPhenotype",
          "label": "Primary Phenotype",
          "type": "list",
          "values": "kp phenotypes"
        },
        {
          "parameter": "secondaryPhenotype",
          "label": "Secondary Phenotype",
          "type": "list",
          "values": "kp phenotypes"
        }
      ],
      "table format": {
        "group by": [
          "Phenotype / phenotype"
        ],
        "compare data": {
          "key field": "Variant ID",
          "fields to compare": [
            "Phenotype / phenotype",
            "P-Value",
            "P-Value(-log10)",
            "Beta",
            "Standard Error",
            "Z Score",
            "MAF",
            "Nearest Genes"
          ]
        },
        "initial sort by": {
          "field": "P-Value",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "dbSNP",
            "raw field": "dbSNP"
          },
          {
            "type": "join multi",
            "field name": "Phenotype / phenotype",
            "fields to join": [
              "leadPhenotype",
              "phenotype"
            ],
            "join by": [
              "_"
            ]
          },
          {
            "type": "join multi",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": [
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "calculate",
            "field name": "P-Value(-log10)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "calculate",
            "field name": "PositionStart",
            "expression": [
              "position",
              "-",
              500000
            ],
            "calculation type": "math"
          },
          {
            "type": "calculate",
            "field name": "PositionEnd",
            "expression": [
              "position",
              "+",
              500000
            ],
            "calculation type": "math"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chromosome",
              "PositionStart",
              "PositionEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "array to string",
            "field name": "Nearest Genes",
            "raw field": "nearest",
            "separate by": ","
          }
        ],
        "top rows": [
          "Variant ID",
          "dbSNP",
          "Phenotype / phenotype",
          "P-Value",
          "Beta",
          "Standard Error",
          "Z Score",
          "MAF",
          "Nearest Genes",
          "Position",
          "PositionStart",
          "PositionEnd",
          "Region"
        ],
        "locus field": "Variant ID",
        "rows per page": 20
      },
      "visualizer": {
        "type": "manhattan bitmap plot",
        "x axis field": "Locus",
        "y axis field": "P-Value(-log10)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value"
        ],
        "height": 100
      }
    }
  ]
}
